// ================================
// Extract incoming data
// ================================
const body = $json.body;

// ================================
// BASIC VALIDATION (IDENTITY)
// ================================
if (!body.billNumber) throw new Error("Bill Number is required");
if (!body.meterNumber && !body.accountNumber) {
  throw new Error("Meter or Account Number is required");
}

// ================================
// BILL PERIOD
// ================================
if (!body.billPeriod?.from || !body.billPeriod?.to) {
  throw new Error("Bill period dates are required");
}

const from = new Date(body.billPeriod.from);
const to = new Date(body.billPeriod.to);

if (to <= from) {
  throw new Error("Bill To date must be after Bill From date");
}

const billingDays = Math.ceil((to - from) / (1000 * 60 * 60 * 24));

// ================================
// BILL CYCLE REMARK
// ================================
let cycleRemark = "Normal";
if (billingDays < 20) cycleRemark = "Short Cycle";
else if (billingDays > 35 && billingDays <= 60) cycleRemark = "Delayed Bill";
else if (billingDays > 60) cycleRemark = "Abnormally Long";

// ================================
// CONSUMPTION
// ================================
const gross = Number(body.consumption?.grossUnits || 0);
const importU = Number(body.consumption?.importUnits || 0);
const exportU = Number(body.consumption?.exportUnits || 0);

if (gross <= 0) throw new Error("Gross units must be greater than zero");
if (importU < 0 || exportU < 0) throw new Error("Invalid unit values");

// Net grid units (can be negative)
const netUnits = importU - exportU;

// ================================
// CARRY FORWARD (SAVE MODE ONLY)
// ================================
let openingCarryForward = Number(body.carryForward?.opening || 0);

// Financial Year reset (April)
if (from.getMonth() === 3) {
  openingCarryForward = 0;
}

// Adjust with carry forward
const adjustedNetUnits = netUnits - openingCarryForward;

let billableUnits = 0;
let closingCarryForward = 0;

if (adjustedNetUnits > 0) {
  billableUnits = adjustedNetUnits;
} else {
  billableUnits = 0;
  closingCarryForward = Math.abs(adjustedNetUnits);
}

// ================================
// CHARGES
// ================================
const fixed = Number(body.charges?.fixedCharges || 0);
const totalBill = Number(body.charges?.totalBillAmount || 0);
const arrears = Number(body.charges?.arrears || 0);

const currentBill = totalBill - arrears;

// ================================
// UNIT RATE (ONLY IF BILLABLE)
// ================================
let unitRate = 0;
if (billableUnits > 0) {
  const energyAmount = currentBill - fixed;
  unitRate = energyAmount / billableUnits;
}

// ================================
// SOLAR SAVING CALCULATION
// ================================
const billWithoutSolar = billableUnits > 0
  ? (gross * unitRate) + fixed
  : fixed;

const saving = billWithoutSolar - currentBill;
const savingPercent = billWithoutSolar > 0
  ? (saving / billWithoutSolar) * 100
  : 0;

const savingPerDay = billingDays > 0 ? saving / billingDays : 0;
const annualProjection = savingPerDay * 365;

// ================================
// OUTPUT
// ================================
return {
  json: {
    // Identity
    billNumber: body.billNumber.toString().trim(),
    meterNumber: body.meterNumber?.toString().trim() || "",
    accountNumber: body.accountNumber?.toString().trim() || "",

    // Mode
    mode: body.mode || "save",
    entryType: body.entryType || "NEW",
    revisionReason: body.revisionReason || "",

    // Period
    billFrom: body.billPeriod.from,
    billTo: body.billPeriod.to,
    billingDays,
    cycleRemark,

    // Consumption
    grossUnits: gross,
    importUnits: importU,
    exportUnits: exportU,
    netGridUnits: netUnits,
    adjustedNetUnits,
    billableUnits,

    // Carry Forward
    openingCarryForward,
    closingCarryForward,

    // Charges
    fixedCharges: fixed,
    totalBillAmount: totalBill,
    arrearsAmount: arrears,
    currentBillAmount: currentBill,
    unitRate: Number(unitRate.toFixed(2)),

    // Savings
    billWithoutSolar: Number(billWithoutSolar.toFixed(2)),
    solarSavingAmount: Number(saving.toFixed(2)),
    savingPercentage: Number(savingPercent.toFixed(2)),
    savingPerDay: Number(savingPerDay.toFixed(2)),
    annualProjection: Number(annualProjection.toFixed(2)),

    // Metadata
    entryDateTime: new Date().toISOString(),
    activeRecord: "YES",
    workflowVersion: "v2.0.0"
  }
};

