// ==========================================
// CHECK DUPLICATE - After Merge Node
// This function receives merged data:
// - Input 1: Webhook data (from Validate & Calculate)
// - Input 2: Sheet records (from Get All Records)
// ==========================================

try {
  // Get all items from Merge node
  const allItems = $input.all();

  console.log('=== MERGE DEBUG ===');
  console.log('Total items from merge:', allItems.length);

  // First item is webhook data (from Validate & Calculate)
  const webhookItem = allItems[0];
  const webhookData = webhookItem.json;

  console.log('Webhook data keys:', Object.keys(webhookData));

  // Extract bill and meter numbers from webhook data
  const incomingBillNumber = webhookData.billNumber;
  const incomingMeterNumber = webhookData.meterNumber;

  console.log('Incoming Bill Number:', incomingBillNumber);
  console.log('Incoming Meter Number:', incomingMeterNumber);

  // Validate we have the required data
  if (!incomingBillNumber || !incomingMeterNumber) {
    console.error('Missing required data!');
    return {
      json: {
        isDuplicate: false,
        error: true,
        errorMessage: 'Bill Number and Meter Number are required',
        webhookData: webhookData,
        incomingData: webhookData
      }
    };
  }

  // Remaining items (from index 1 onwards) are sheet records
  const sheetRecords = allItems.slice(1);

  console.log('Sheet records to check:', sheetRecords.length);

  // If no sheet records, then no duplicates possible (empty sheet)
  if (sheetRecords.length === 0) {
    console.log('✅ Sheet is empty - no duplicates possible');
    return {
      json: {
        isDuplicate: false,
        duplicateRecord: null,
        incomingData: webhookData,
        totalRecordsChecked: 0,
        // Pass all webhook data forward to next nodes
        ...webhookData
      }
    };
  }

  // Loop through sheet records to find duplicates
  let duplicateFound = false;
  let duplicateRecord = null;

  for (let i = 0; i < sheetRecords.length; i++) {
    const record = sheetRecords[i].json;

    // Get values from sheet record
    const recordMeter = record['Meter Number'] || record.meterNumber;
    const recordBill = record['Bill Number'] || record.billNumber;
    const recordActive = record['Active Record'] || record.activeRecord;

    console.log(`Record ${i + 1}:`, {
      bill: recordBill,
      meter: recordMeter,
      active: recordActive
    });

    // Check if this record matches our incoming bill
    const isMeterMatch = recordMeter && recordMeter.toString() === incomingMeterNumber.toString();
    const isBillMatch = recordBill && recordBill.toString() === incomingBillNumber.toString();
    const isActive = !recordActive || recordActive.toString().toUpperCase() === 'YES';

    if (isMeterMatch && isBillMatch && isActive) {
      duplicateFound = true;
      duplicateRecord = record;
      console.log('❌ DUPLICATE FOUND at record', i + 1);
      break;
    }
  }

  console.log('=== RESULT ===');
  console.log('Duplicate Found:', duplicateFound);
  console.log('Records Checked:', sheetRecords.length);

  // Return result
  return {
    json: {
      isDuplicate: duplicateFound,
      duplicateRecord: duplicateRecord,
      incomingData: webhookData,
      totalRecordsChecked: sheetRecords.length,
      searchCriteria: {
        billNumber: incomingBillNumber,
        meterNumber: incomingMeterNumber
      },
      // Pass all webhook data forward to next nodes
      ...webhookData
    }
  };

} catch (error) {
  console.error('❌ Error in duplicate check:', error.message);
  console.error('Stack:', error.stack);

  return {
    json: {
      isDuplicate: false,
      error: true,
      errorMessage: error.message,
      errorStack: error.stack
    }
  };
}

