    return {
      json: {
        found: false,
        error: true,
        message: 'Could not access webhook data: ' + e.message
      }
    };
  }

  const billNumber = updateData.billNumber;
  const meterNumber = updateData.meterNumber;
  const accountNumber = updateData.accountNumber;

  console.log('=== UPDATE REQUEST ===');
  console.log('Looking for bill:', billNumber);
  console.log('Meter:', meterNumber);
  console.log('Account:', accountNumber);
  console.log('Full update data:', JSON.stringify(updateData, null, 2));

  // Validate required fields
  if (!billNumber || !meterNumber || !accountNumber) {
    return {
      json: {
        found: false,
        error: true,
        message: 'Missing required fields: billNumber, meterNumber, or accountNumber'
      }
    };
  }

  // Get all sheet records from input
  const allRecords = $input.all();

  console.log('Total records to search:', allRecords.length);

  // Find the bill to update
  let foundBill = null;
  let foundIndex = -1;

  for (let i = 0; i < allRecords.length; i++) {
    const record = allRecords[i].json;

    const recordBill = record['Bill Number'];
    const recordMeter = record['Meter Number'];
    const recordAccount = record['Account Number'];
    const recordActive = record['Active Record'];

    // Compare values
    if (
      recordBill && recordBill.toString() === billNumber.toString() &&
      recordMeter && recordMeter.toString() === meterNumber.toString() &&
      recordAccount && recordAccount.toString() === accountNumber.toString() &&
      recordActive && recordActive.toString().toUpperCase() === 'YES'
    ) {
      foundBill = record;
      foundIndex = record.row_number || (i + 2);
      console.log('✅ Found bill at row:', foundIndex);
      break;
    }
  }

  if (foundBill) {
    console.log('✅ Bill found, extracting update values...');

    // Extract values from NESTED structure
    const consumption = updateData.consumption || {};
    const charges = updateData.charges || {};
    const calculation = updateData.calculation || {};
    const billPeriod = updateData.billPeriod || {};

    const gross = parseFloat(consumption.grossUnits);
    const importU = parseFloat(consumption.importUnits);
    const exportU = parseFloat(consumption.exportUnits);
    const fixed = parseFloat(charges.fixedCharges);
    const total = parseFloat(charges.totalBillAmount);

    console.log('Extracted values:', {
      gross,
      importU,
      exportU,
      fixed,
      total
    });

    // Validate extracted values
    if (isNaN(gross) || isNaN(importU) || isNaN(exportU) || isNaN(fixed) || isNaN(total)) {
      return {
        json: {
          found: false,
          error: true,
          message: 'Invalid numeric values in update data',
          receivedData: {
            gross,
            importU,
            exportU,
            fixed,
            total
          }
        }
      };
    }

    // Recalculate
    const net = importU - exportU;
    const direct = gross - importU;
    const currentBill = total;
    const unitRate = net > 0 ? (currentBill - fixed) / net : 0;
    const billWithoutSolar = (gross * unitRate) + fixed;
    const saving = billWithoutSolar - currentBill;
    const savingPercent = billWithoutSolar > 0 ? (saving / billWithoutSolar) * 100 : 0;

    console.log('Calculated values:', {
      net,
      direct,
      unitRate: unitRate.toFixed(2),
      billWithoutSolar: billWithoutSolar.toFixed(2),
      saving: saving.toFixed(2),
      savingPercent: savingPercent.toFixed(2)
    });

    return {
      json: {
        found: true,
        rowNumber: foundIndex,
        billNumber: billNumber,
        meterNumber: meterNumber,
        accountNumber: accountNumber,
        entryType: 'EDIT',
        revisionReason: 'Updated by user',

        // Updated values
        grossUnits: gross,
        importUnits: importU,
        exportUnits: exportU,
        netUnits: parseFloat(net.toFixed(2)),
        directSolar: parseFloat(direct.toFixed(2)),
        fixedCharges: fixed,
        totalBillAmount: total,
        unitRate: parseFloat(unitRate.toFixed(2)),
        billWithoutSolar: parseFloat(billWithoutSolar.toFixed(2)),
        solarSavingAmount: parseFloat(saving.toFixed(2)),
        savingPercentage: parseFloat(savingPercent.toFixed(2)),

        // Date fields - use updated values if provided, otherwise keep original
        billFromDate: billPeriod.from || foundBill['Bill From Date'],
        billToDate: billPeriod.to || foundBill['Bill To Date'],
        billingDays: billPeriod.days || foundBill['Billing Days'],

        // Metadata
        lastModifiedDateTime: new Date().toISOString(),
        activeRecord: 'YES'
      }
    };
  } else {
    console.log('❌ Bill not found');
    return {
      json: {
        found: false,
        error: true,
        message: 'Bill not found or already inactive',
        searchedFor: {
          billNumber,
          meterNumber,
          accountNumber
        },
        totalRecordsSearched: allRecords.length
      }
    };
  }

} catch (error) {
  console.error('❌ Error in Find Bill to Update:', error.message);
  console.error('Stack:', error.stack);

  return {
    json: {
      found: false,
      error: true,
      message: error.message,
      stack: error.stack
    }
  };
}

