      meterNumber = webhookData.query.meterNumber;
      accountNumber = webhookData.query.accountNumber;
    }
  } catch (webhookError) {
    console.error('Could not access webhook node:', webhookError.message);
  }

  console.log('=== AUTHENTICATION REQUEST ===');
  console.log('Looking for Meter:', meterNumber);
  console.log('Looking for Account:', accountNumber);

  // Validate we have the credentials
  if (!meterNumber || !accountNumber) {
    return {
      json: {
        status: 'error',
        authenticated: false,
        billCount: 0,
        bills: [],
        message: 'Missing meterNumber or accountNumber in webhook request'
      }
    };
  }

  // Get sheet records from current input
  const allRecords = $input.all();

  console.log('Total records from sheet:', allRecords.length);

  // Filter records for this user (Active records only)
  const userBills = [];

  for (const item of allRecords) {
    const record = item.json;

    // Get values from record (handle potential undefined)
    const recordMeter = record['Meter Number'];
    const recordAccount = record['Account Number'];
    const recordActive = record['Active Record'];

    console.log('Checking record:', {
      bill: record['Bill Number'],
      meter: recordMeter,
      account: recordAccount,
      active: recordActive
    });

    // Check if this record matches the user
    // Use optional chaining and nullish coalescing to handle undefined
    const meterMatch = recordMeter?.toString().trim() === meterNumber?.toString().trim();
    const accountMatch = recordAccount?.toString().trim() === accountNumber?.toString().trim();
    const activeMatch = recordActive?.toString().toUpperCase().trim() === 'YES';

    if (meterMatch && accountMatch && activeMatch) {
      console.log('✅ Match found! Bill:', record['Bill Number']);
      userBills.push(record);
    }
  }

  console.log('=== AUTHENTICATION RESULT ===');
  console.log('Bills found for user:', userBills.length);

  // Return response
  if (userBills.length > 0) {
    console.log('✅ Authentication successful');

    return {
      json: {
        status: 'success',
        authenticated: true,
        billCount: userBills.length,
        bills: userBills,
        message: `Found ${userBills.length} bill(s)`
