} catch (error) {
  console.error('❌ Authentication error:', error.message);
  console.error('Stack:', error.stack);

  return {
    json: {
      status: 'error',
      authenticated: false,
      billCount: 0,
      bills: [],
      message: `Error: ${error.message}`
    }
  };
}

const item = $input.all()[0];

console.log('=== NODE 2: Prepare Image ===');

// Get binary data
if (!item.binary || !item.binary.data) {
  throw new Error('No image data received');
}

const binaryData = item.binary.data;
let base64Image = binaryData.data;
const mimeType = binaryData.mimeType || 'image/jpeg';

console.log('Original MIME:', mimeType);
console.log('Original Base64 length:', base64Image.length);
console.log('First 50 chars:', base64Image.substring(0, 50));

// CRITICAL: Remove data URI prefix if present
// Example: "data:image/jpeg;base64,/9j/4AAQ..." 
// Should be: "/9j/4AAQ..."
if (base64Image.includes('data:')) {
  console.log('⚠️ Found data URI prefix, removing...');
  base64Image = base64Image.split(',')[1];
}

// Remove any whitespace or newlines
base64Image = base64Image.replace(/\s/g, '');

// Remove leading/trailing = signs that might cause issues
base64Image = base64Image.replace(/^=+/, '').replace(/=+$/, '');

// Verify base64 format (should start with / or a-zA-Z0-9)
const firstChar = base64Image.charAt(0);
console.log('First character after cleaning:', firstChar);

if (firstChar === '=' || firstChar === '') {
  throw new Error('Invalid base64 string after cleaning');
}

console.log('Cleaned Base64 length:', base64Image.length);
console.log('First 50 chars after clean:', base64Image.substring(0, 50));
console.log('Last 50 chars:', base64Image.substring(base64Image.length - 50));

// Ensure proper base64 padding (must be multiple of 4)
const remainder = base64Image.length % 4;
if (remainder !== 0) {
  const paddingNeeded = 4 - remainder;
  console.log(`Adding ${paddingNeeded} padding characters`);
  base64Image += '='.repeat(paddingNeeded);
}

console.log('Final Base64 length:', base64Image.length);
console.log('✅ Image prepared successfully');

return [{
  json: {
    base64Image: base64Image,
    mimeType: mimeType
  }
}];

