try {
  const response = $input.all()[0].json;

  console.log('=== GEMINI RESPONSE ===');
  console.log(JSON.stringify(response, null, 2));

  if (response.error) {
    return [{
      json: {
        success: false,
        error: response.error.message || 'Gemini API error'
      }
    }];
  }

  if (!response.candidates || !response.candidates[0]) {
    return [{
      json: {
        success: false,
        error: 'No candidates in response'
      }
    }];
  }

  const candidate = response.candidates[0];
  let content = candidate.content.parts[0].text;

  console.log('=== RAW CONTENT ===');
  console.log(content);

  // Extract JSON from possible markdown or extra text
  let jsonString = content;

  // Method 1: Extract from ```json block
  const jsonMatch = content.match(/```json\s*\n([\s\S]*?)\n```/);
  if (jsonMatch) {
    jsonString = jsonMatch[1];
    console.log('Extracted from markdown block');
  } else {
    // Method 2: Extract before "---" or analysis markers
    const markers = ['---', '**PHASE', '\n\n**', 'PHASE 2'];
    for (let marker of markers) {
      if (content.includes(marker)) {
        jsonString = content.split(marker)[0];
        console.log('Extracted before:', marker);
        break;
      }
    }

    // Clean any remaining markdown
    jsonString = jsonString.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  }

  console.log('=== CLEANED JSON ===');
  console.log(jsonString);

  // Parse JSON
  let extracted;
  try {
    extracted = JSON.parse(jsonString);
  } catch (jsonError) {
    console.error('JSON Parse Error:', jsonError);
    return [{
      json: {
        success: false,
        error: 'Failed to parse JSON: ' + jsonError.message,
        rawContent: content.substring(0, 1000)
      }
    }];
  }

  console.log('=== PARSED DATA ===');
  console.log(JSON.stringify(extracted, null, 2));

  // Calculate billingDays if missing
  let billingDays = extracted.billingDays;
  if (!billingDays && extracted.billFrom && extracted.billTo) {
    try {
      const fromParts = extracted.billFrom.split('/');
      const toParts = extracted.billTo.split('/');
      const fromDate = new Date(fromParts[2], fromParts[1] - 1, fromParts[0]);
      const toDate = new Date(toParts[2], toParts[1] - 1, toParts[0]);
      billingDays = Math.round((toDate - fromDate) / (1000 * 60 * 60 * 24));
      console.log('Calculated billing days:', billingDays);
    } catch (e) {
      console.error('Date calc error:', e);
    }
  }

  // Calculate solarGenerated if missing
  let solarGenerated = extracted.solarGenerated;
  if (!solarGenerated && extracted.grossUnits && extracted.importUnits && extracted.exportUnits) {
    solarGenerated = extracted.grossUnits - extracted.importUnits + extracted.exportUnits;
    console.log('Calculated solar:', solarGenerated);
  }

  // Build clean data
  const cleanData = {
    billNumber: extracted.billNumber || null,
    accountNumber: extracted.accountNumber || null,
    meterNumber: extracted.meterNumber || null,
    billFrom: extracted.billFrom || null,
    billTo: extracted.billTo || null,
    billingDays: billingDays ? parseInt(billingDays) : null,
    importUnits: extracted.importUnits ? parseInt(extracted.importUnits) : null,
    exportUnits: extracted.exportUnits ? parseInt(extracted.exportUnits) : null,
    grossUnits: extracted.grossUnits ? parseInt(extracted.grossUnits) : null,
    solarGenerated: solarGenerated ? parseInt(solarGenerated) : null,
    totalBill: extracted.totalBill ? Math.round(parseFloat(extracted.totalBill)) : null,
    fixedCharges: extracted.fixedCharges ? Math.round(parseFloat(extracted.fixedCharges)) : null,
    arrears: extracted.arrears ? Math.round(parseFloat(extracted.arrears)) : 0
  };

  // Remove nulls
  const finalData = {};
  for (let key in cleanData) {
    if (cleanData[key] !== null && cleanData[key] !== undefined) {
      finalData[key] = cleanData[key];
    }
  }

  console.log('=== FINAL DATA ===');
  console.log(JSON.stringify(finalData, null, 2));

  // Log token usage
  if (response.usageMetadata) {
    console.log('=== TOKEN USAGE ===');
    console.log('Total:', response.usageMetadata.totalTokenCount);
    console.log('Prompt:', response.usageMetadata.promptTokenCount);
    console.log('Response:', response.usageMetadata.candidatesTokenCount);
  }

  return [{
    json: {
      success: true,
      data: finalData,
      fieldsExtracted: Object.keys(finalData).length,
      timestamp: new Date().toISOString()
    }
  }];

} catch (error) {
  console.error('=== PARSE ERROR ===');
  console.error(error);
  return [{
    json: {
      success: false,
      error: 'Parse error: ' + error.message
    }
  }];
}
